mapper.select:
SELECT id, activity_id, sku_id, create_time
FROM group_buy_market_better.activity_product
WHERE activity_id = #{activityId}

SELECT id, activity_id, sku_id, create_time
FROM group_buy_market_better.activity_product
WHERE sku_id = #{skuId}

SELECT ap.id, ap.activity_id, ap.sku_id, ap.create_time
FROM group_buy_market_better.activity_product ap
         JOIN group_buy_market_better.activity_config ac
              ON ap.activity_id = ac.activity_id
WHERE ap.sku_id = #{skuId}
  AND ac.status = 1
  AND ac.start_time < #{endTime}
  AND ac.end_time > #{startTime}
